package com.example.melonstools.data;

import com.example.melonstools.department.DepartmentPolicy;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.level.saveddata.SavedData;

import java.util.*;

/** Procurement/material request ledger backed by approved DepartmentApplication sources. */
public class ProcurementSavedData extends SavedData {
    public static final String DATA_NAME = "melon_procurements";
    public static final String REQUEST = "request", APPROVED = "approved", ORDERED = "ordered", RECEIVED = "received", COMPLETED = "completed", REJECTED = "rejected", CANCELLED = "cancelled", FAILED = "failed";
    public static final String CAT_RESEARCH = "research", CAT_WEAPON = "weapon", CAT_GENERAL = "general", CAT_EMERGENCY = "emergency";
    public static final long LOW_VALUE_LIMIT = 1000L, FACILITY_REVIEW_LIMIT = 10000L;
    private final List<Record> records = new ArrayList<>(); private int sequence;

    public static ProcurementSavedData get(ServerLevel level) { return level.getDataStorage().computeIfAbsent(ProcurementSavedData::load, ProcurementSavedData::new, DATA_NAME); }
    public static ProcurementSavedData load(CompoundTag tag) { ProcurementSavedData d = new ProcurementSavedData(); d.sequence = tag.getInt("Sequence"); ListTag list = tag.getList("Records", Tag.TAG_COMPOUND); for (int i=0;i<list.size();i++) d.records.add(Record.load(list.getCompound(i))); return d; }
    @Override public CompoundTag save(CompoundTag tag) { tag.putInt("Sequence", sequence); ListTag list = new ListTag(); for (Record r: records) list.add(r.save()); tag.put("Records", list); return tag; }
    public List<Record> records() { return Collections.unmodifiableList(records); } public Record find(String id){for(Record r:records)if(r.id.equals(id))return r;return null;}

    public Record create(ServerPlayer actor, JsonObject in) {
        if (actor == null) return null;
         DepartmentPolicy.Identity actorIdentity=DepartmentPolicy.identity(actor);
         if (!actor.hasPermissions(2) && !DepartmentPolicy.isFacilityDirector(actorIdentity.department(),actorIdentity.position(),actorIdentity.level()) && !(DepartmentPolicy.DEPT_LOGISTICS.equals(actorIdentity.department()) && actorIdentity.level()>=3)) return null;
        String source = get(in, "sourceApplicationId", get(in, "approvalApplicationId", ""));
        DepartmentApplicationSavedData.Application app = DepartmentApplicationSavedData.get(actor.serverLevel()).find(source);
        Record r = new Record(); r.id = "proc-" + (++sequence); r.status = REQUEST; r.category = normalizeCategory(get(in, "category", inferCategory(app))); r.department = DepartmentPolicy.identity(actor).department(); r.requesterUuid = actor.getUUID().toString(); r.requesterName = actor.getScoreboardName(); r.itemsJson = getItems(in, app); r.amount = Math.max(0L, getLong(in, "amount", getLong(in, "estimatedCost", 0L))); r.riskLevel = normalizeRisk(get(in, "risk", get(in, "riskLevel", app == null ? "low" : app.riskLevel))); r.sourceApplicationId = source; r.reason = get(in, "reason", app == null ? "" : app.reason); r.createdAt = r.updatedAt = System.currentTimeMillis();
        boolean valid = isApprovedSource(app, r.category);
         if (valid && r.amount > 0L && FacilityFundManager.get(actor.serverLevel()).reserveBudget(r.amount,actor.getScoreboardName(),r.id)) { r.reservedBudget=r.amount; r.budgetStatus="reserved"; r.reservedAt=r.createdAt; }
         else if (valid) { r.status=FAILED; r.budgetStatus="failed"; }
        if (!valid || r.amount <= 0L || r.itemsJson.isBlank()) r.status = REJECTED;
        else if (isLowRisk(r) && !FAILED.equals(r.status)) r.status = APPROVED; // low-value logistics-3 path may order directly after creation
        records.add(r); setDirty();
        OperationAuditSavedData.get(actor.serverLevel()).record(actor, "procurement_create", r.id, valid ? "ok" : "denied", "sourceApplicationId=" + source + ";route=" + routeFor(r), "", r.status);
        return r;
    }

    /** Approval after source app: low logistics3, high/weapon/emergency logistics4, large/high-risk facility5. */
    public boolean approve(String id, ServerPlayer actor, String note){ Record r=find(id); if(r==null||actor==null||!REQUEST.equals(r.status)&&!APPROVED.equals(r.status))return false; boolean ok=canApprove(actor,r); if(ok){r.status=APPROVED;r.updatedAt=System.currentTimeMillis();setDirty();} audit(actor,"procurement_approve",r,ok,note); return ok; }
    public boolean order(String id, ServerPlayer actor, String note){ Record r=find(id); if(r==null||actor==null||!APPROVED.equals(r.status))return false; boolean permitted=canExecute(actor,r), ok=false; if(permitted){ok=r.reservedBudget==r.amount&&FacilityFundManager.get(actor.serverLevel()).withdrawReserved(r.amount,actor.getScoreboardName(),"procurement_payout:"+r.id+" "+note,r.id); long now=System.currentTimeMillis(); if(ok){r.status=ORDERED;r.paymentId="facility-fund:"+r.id;r.paidAt=now;r.budgetStatus="released";r.releasedAt=now;r.reservedBudget=0L;r.executorUuid=actor.getUUID().toString();r.executorName=actor.getScoreboardName();r.orderedAt=r.updatedAt=now;}else{FacilityFundManager.get(actor.serverLevel()).releaseBudget(r.amount,actor.getScoreboardName(),r.id);r.status=FAILED;r.budgetStatus="released";r.releasedAt=now;r.reservedBudget=0L;r.updatedAt=now;}setDirty();} audit(actor,"procurement_order",r,permitted&&ok,permitted?note:"permission_denied_or_fund_insufficient"); return permitted&&ok; }
    public boolean receive(String id, ServerPlayer actor, String note){ Record r=find(id); if(r==null||actor==null||!ORDERED.equals(r.status))return false; boolean ok=canExecute(actor,r); if(ok){r.status=RECEIVED;r.receivedAt=r.updatedAt=System.currentTimeMillis();setDirty();} audit(actor,"procurement_receive",r,ok,"manual_receipt_only_no_inventory_spawn;"+note); return ok; }
    public boolean complete(String id, ServerPlayer actor, String note){ Record r=find(id); if(r==null||actor==null||!RECEIVED.equals(r.status))return false; boolean ok=canExecute(actor,r)||r.requesterUuid.equals(actor.getUUID().toString()); if(ok){r.status=COMPLETED;r.updatedAt=System.currentTimeMillis();setDirty();} audit(actor,"procurement_complete",r,ok,note); return ok; }
    public boolean reject(String id, ServerPlayer actor, String reason){ Record r=find(id); if(r==null||actor==null||isTerminalStatus(r.status))return false; boolean ok=canApprove(actor,r); if(ok){releaseReservation(r);r.status=REJECTED;r.updatedAt=System.currentTimeMillis();setDirty();} audit(actor,"procurement_reject",r,ok,reason); return ok; }
    public boolean cancel(String id, ServerPlayer actor, String reason){ Record r=find(id); if(r==null||actor==null||isTerminalStatus(r.status))return false; boolean ok=r.requesterUuid.equals(actor.getUUID().toString())||canApprove(actor,r); if(ok){releaseReservation(r);r.status=CANCELLED;r.updatedAt=System.currentTimeMillis();setDirty();} audit(actor,"procurement_cancel",r,ok,reason); return ok; }

    public JsonObject toJsonFor(ServerPlayer viewer) { JsonObject root = new JsonObject(); JsonArray arr = new JsonArray(); for (Record r: records) arr.add(r.toJson()); root.add("items", arr); root.addProperty("stateMachine", "request->approved->ordered->received->completed; rejected/cancelled terminal and audited"); root.addProperty("route", "low general logistics3; high/weapon/emergency logistics4; large/high risk facility director5"); JsonObject summary = new JsonObject(); long reserved = 0L; int pending = 0; for (Record r : records) { if (r.reservedBudget > 0L && !isTerminalStatus(r.status)) reserved += r.reservedBudget; if (!isTerminalStatus(r.status)) pending++; } long ledger=viewer==null?0L:FacilityFundManager.get(viewer.serverLevel()).getBalance(); summary.addProperty("ledgerBalanceText", String.valueOf(ledger)); summary.addProperty("reservedBudgetText", String.valueOf(reserved)); summary.addProperty("availableBudgetText", String.valueOf(Math.max(0L,ledger-reserved))); summary.addProperty("pendingCount", pending); root.add("summary", summary); return root; }
    private static boolean isApprovedSource(DepartmentApplicationSavedData.Application app,String cat){ if(app==null)return false; if(!DepartmentApplicationSavedData.STATUS_APPROVED.equals(app.status)&&!DepartmentApplicationSavedData.STATUS_CARD_CHANGE_REQUIRED.equals(app.status)&&!DepartmentApplicationSavedData.STATUS_COMPLETED.equals(app.status))return false; return CAT_RESEARCH.equals(cat)?DepartmentApplicationSavedData.TYPE_RESEARCH_PURCHASE.equals(app.type):true; }
    private static boolean isLowRisk(Record r){return CAT_GENERAL.equals(r.category)&&r.amount<=LOW_VALUE_LIMIT&&!"high".equalsIgnoreCase(r.riskLevel);} private static boolean requiresFacility(Record r){return r.amount>=FACILITY_REVIEW_LIMIT||"high".equalsIgnoreCase(r.riskLevel);} private static boolean canApprove(ServerPlayer a,Record r){DepartmentPolicy.Identity id=DepartmentPolicy.identity(a); if(a.hasPermissions(2)||DepartmentPolicy.isFacilityDirector(id.department(),id.position(),id.level()))return true; if(requiresFacility(r))return false; if(isLowRisk(r))return DepartmentPolicy.DEPT_LOGISTICS.equals(id.department())&&id.level()>=3; return DepartmentPolicy.isLogisticsSupervisor(id.department(),id.position(),id.level());} private static boolean canExecute(ServerPlayer a,Record r){DepartmentPolicy.Identity id=DepartmentPolicy.identity(a); if(a.hasPermissions(2)||DepartmentPolicy.isFacilityDirector(id.department(),id.position(),id.level()))return true; if(isLowRisk(r))return DepartmentPolicy.DEPT_LOGISTICS.equals(id.department())&&id.level()>=3; return DepartmentPolicy.isLogisticsSupervisor(id.department(),id.position(),id.level());}
    private static void releaseReservation(Record r){ if(r!=null&&r.reservedBudget>0L){r.reservedBudget=0L;r.budgetStatus="released";r.releasedAt=System.currentTimeMillis();r.version++;} }
     private void audit(ServerPlayer a,String act,Record r,boolean ok,String note){OperationAuditSavedData.get(a.serverLevel()).record(a,act,r==null?"":r.id,ok?"ok":"denied",note,"",r==null?"":r.status);} public static boolean isTerminalStatus(String s) { return COMPLETED.equals(s) || REJECTED.equals(s) || CANCELLED.equals(s) || FAILED.equals(s); }
    public static String normalizeCategory(String raw) { String v = raw == null ? "" : raw.trim().toLowerCase(Locale.ROOT); return switch (v) { case CAT_RESEARCH, "科研" -> CAT_RESEARCH; case CAT_WEAPON, "danger", "危险品", "武器" -> CAT_WEAPON; case CAT_EMERGENCY, "紧急" -> CAT_EMERGENCY; default -> CAT_GENERAL; }; }
    private static String normalizeRisk(String r){return "high".equalsIgnoreCase(r)||"高".equals(r)?"high":"low";} private static String inferCategory(DepartmentApplicationSavedData.Application a){return a!=null&&DepartmentApplicationSavedData.TYPE_RESEARCH_PURCHASE.equals(a.type)?CAT_RESEARCH:CAT_GENERAL;} private static String getItems(JsonObject o,DepartmentApplicationSavedData.Application a){return o!=null&&o.has("items")?o.get("items").toString():(a==null?"[]":a.requestedItems);} private static String routeFor(Record r){return isLowRisk(r)?"logistics3":requiresFacility(r)?"facility5":"logistics4";} private static String get(JsonObject o,String k,String d){ return o!=null&&o.has(k)&&!o.get(k).isJsonNull()?o.get(k).getAsString():d; } private static long getLong(JsonObject o,String k,long d){ try{return o!=null&&o.has(k)?o.get(k).getAsLong():d;}catch(Throwable t){return d;} }

    public static class Record { public String id="", status=REQUEST, category=CAT_GENERAL, requesterUuid="", requesterName="", department="", itemsJson="[]", riskLevel="low", executorUuid="", executorName="", sourceApplicationId="", reason="", paymentId="", budgetStatus="unreserved", idempotencyKey=""; public long amount, reservedBudget, createdAt, updatedAt, paidAt, orderedAt, receivedAt, reservedAt, releasedAt, version; CompoundTag save(){ CompoundTag t=new CompoundTag(); t.putString("Id",id); t.putString("Status",status); t.putString("Category",category); t.putString("RequesterUuid",requesterUuid); t.putString("RequesterName",requesterName); t.putString("Department",department); t.putString("ItemsJson",itemsJson); t.putLong("Amount",amount); t.putLong("ReservedBudget",reservedBudget); t.putString("BudgetStatus",budgetStatus); t.putLong("ReservedAt",reservedAt); t.putLong("ReleasedAt",releasedAt); t.putLong("Version",version); t.putString("PaymentId",paymentId); t.putString("IdempotencyKey",idempotencyKey); t.putString("RiskLevel",riskLevel); t.putString("ExecutorUuid",executorUuid); t.putString("ExecutorName",executorName); t.putString("SourceApplicationId",sourceApplicationId); t.putString("Reason",reason); t.putLong("CreatedAt",createdAt); t.putLong("UpdatedAt",updatedAt); t.putLong("PaidAt",paidAt); t.putLong("OrderedAt",orderedAt); t.putLong("ReceivedAt",receivedAt); return t; } static Record load(CompoundTag t){ Record r=new Record(); r.id=t.getString("Id"); r.status=t.getString("Status"); r.category=t.getString("Category"); r.requesterUuid=t.getString("RequesterUuid"); r.requesterName=t.getString("RequesterName"); r.department=t.getString("Department"); r.itemsJson=t.getString("ItemsJson"); r.amount=t.getLong("Amount"); r.reservedBudget=t.getLong("ReservedBudget"); r.budgetStatus=t.getString("BudgetStatus"); if(r.budgetStatus.isEmpty()) r.budgetStatus="unreserved"; r.reservedAt=t.getLong("ReservedAt"); r.releasedAt=t.getLong("ReleasedAt"); r.version=t.getLong("Version"); r.paymentId=t.getString("PaymentId"); r.idempotencyKey=t.getString("IdempotencyKey"); r.riskLevel=t.getString("RiskLevel"); r.executorUuid=t.getString("ExecutorUuid"); r.executorName=t.getString("ExecutorName"); r.sourceApplicationId=t.getString("SourceApplicationId"); r.reason=t.getString("Reason"); r.createdAt=t.getLong("CreatedAt"); r.updatedAt=t.getLong("UpdatedAt"); r.paidAt=t.getLong("PaidAt"); r.orderedAt=t.getLong("OrderedAt"); r.receivedAt=t.getLong("ReceivedAt"); return r; } JsonObject toJson(){ JsonObject o=new JsonObject(); o.addProperty("id",id); o.addProperty("status",status); o.addProperty("category",category); o.addProperty("requesterUuid",requesterUuid); o.addProperty("requesterName",requesterName); o.addProperty("department",department); o.addProperty("items",itemsJson); o.addProperty("amount",amount); o.addProperty("reservedBudget",reservedBudget); o.addProperty("budgetStatus",budgetStatus); o.addProperty("reservedAt",reservedAt); o.addProperty("releasedAt",releasedAt); o.addProperty("version",version); o.addProperty("paymentId",paymentId); o.addProperty("riskLevel",riskLevel); o.addProperty("executorUuid",executorUuid); o.addProperty("executorName",executorName); o.addProperty("sourceApplicationId",sourceApplicationId); o.addProperty("reason",reason); o.addProperty("createdAt",createdAt); o.addProperty("updatedAt",updatedAt); o.addProperty("paidAt",paidAt); o.addProperty("orderedAt",orderedAt); o.addProperty("receivedAt",receivedAt); return o; } }
}
